import java.util.StringTokenizer

class CodeforcesC : Runnable {
    private val onlineJudge = System.getProperty("ONLINE_JUDGE") != null

    private lateinit var input: BufferedReader
    private lateinit var out: PrintWriter
    private var tokenizer = StringTokenizer("")

    private var timeBegin = 0L
    private var timeEnd = 0L
    private var memoryTotal = 0L
    private var memoryFree = 0L

    private val debug = false

    @Throws(FileNotFoundException::class)
    private fun init() {
        if (onlineJudge) {
            input = BufferedReader(InputStreamReader(System.`in`))
            out = PrintWriter(System.out)
        } else {
            input = BufferedReader(FileReader("input.txt"))
            out = PrintWriter("output.txt")
        }
    }

    @Throws(IOException::class)
    private fun readString(): String? {
        while (!tokenizer.hasMoreTokens()) {
            tokenizer = try {
                StringTokenizer(input.readLine())
            } catch (e: Exception) {
                return null
            }
        }
        return tokenizer.nextToken()
    }

    @Throws(IOException::class)
    private fun readInt(): Int = readString()!!.toInt()

    @Throws(IOException::class)
    private fun readLong(): Long = readString()!!.toLong()

    @Throws(IOException::class)
    private fun readDouble(): Double = readString()!!.toDouble()

    private fun time() {
        timeEnd = System.currentTimeMillis()
        System.err.println("Time = ${timeEnd - timeBegin}")
    }

    private fun memory() {
        memoryFree = Runtime.getRuntime().freeMemory()
        System.err.println("Memory = ${(memoryTotal - memoryFree) shr 10} KB")
    }

    private fun debug(vararg objects: Any?) {
        if (debug) {
            for (obj in objects) {
                System.err.println(obj.toString())
            }
        }
    }

    @Throws(IOException::class)
    private fun readIntArray(n: Int): IntArray {
        return IntArray(n) { readInt() }
    }

    override fun run() {
        try {
            timeBegin = System.currentTimeMillis()
            memoryTotal = Runtime.getRuntime().freeMemory()
            init()
            solve()
            out.close()
            time()
            memory()
        } catch (e: Exception) {
            e.printStackTrace(System.err)
            System.exit(-1)
        }
    }

    @Throws(IOException::class)
    private fun solve() {
        val l = readInt()
        val r = readInt()

        val n = 9
        val ten = IntArray(n + 1)
        ten[0] = 1

        for (i in 1..n) {
            ten[i] = 10 * ten[i - 1]
        }

        var answer = 0L
        val luckyNumbers = ArrayList<Long>()

        for (length in 1..n) {
            for (cur in 0 until (1 shl length)) {
                var value = 0
                for (j in 0 until length) {
                    value += if (((1 shl j) and cur) == (1 shl j)) {
                        ten[j] * 7
                    } else {
                        ten[j] * 4
                    }
                }
                luckyNumbers.add(value.toLong())
            }
        }

        luckyNumbers.add(4_444_444_444L)

        var lastNumber = l.toLong()

        for (luckyNumber in luckyNumbers) {
            if (luckyNumber > r.toLong()) {
                answer += (r.toLong() - lastNumber + 1L) * luckyNumber
                break
            }
            if (luckyNumber >= l.toLong()) {
                answer += (luckyNumber - lastNumber + 1L) * luckyNumber
                lastNumber = luckyNumber + 1L
            }
        }

        out.println(answer)
    }

    companion object {
        @JvmStatic
        fun main(args: Array<String>) {
            Thread(null, CodeforcesC(), "", 128L * (1L shl 20)).start()
        }
    }
