        for (long luckyNumber : luckyNumbers) {
            if (luckyNumber > r) {
                answer += 1l * (r - lastNumber + 1) * luckyNumber;
                break;
            }
            if (luckyNumber >= l) {
                answer += 1l * (luckyNumber - lastNumber + 1) * luckyNumber;
                lastNumber = luckyNumber + 1;
            }
        }

        out.println(answer);
    }
